<template>
  <div class="library">
    <h2>眼底图片库</h2>
    <div class="search-container">
      <input type="text" v-model="searchQuery" placeholder="搜索...">
      <button @click="searchImages">搜索</button>
    </div>
    <div class="filter-container">
      <select v-model="selectedDisease">
        <option value="">所有疾病</option>
        <option v-for="disease in diseases" :key="disease.id" :value="disease.id">
          {{ disease.name }}
        </option>
      </select>
      <select v-model="selectedType">
        <option value="">所有类型</option>
        <option v-for="type in types" :key="type.id" :value="type.id">
          {{ type.name }}
        </option>
      </select>
    </div>

    <!-- 上传图片区域 -->
    <div class="upload-container">
      <div class="upload-box" @click="openFileInput">
        <span class="plus-icon">+</span>
        <span class="upload-text">上传图片</span>
        <input type="file" ref="fileInput" @change="handleFileUpload" accept="image/*" style="display: none;">
      </div>
      <div class="type-selection">
        <label for="imageType">选择类型:</label>
        <select id="imageType" v-model="selectedUploadType">
          <option value="">请选择类型</option>
          <option value="其他异常">其他异常</option>
          <option value="近视">近视</option>
          <option value="高血压">高血压</option>
          <option value="AMD">AMD</option>
          <option value="白内障">白内障</option>
          <option value="青光眼">青光眼</option>
          <option value="糖尿病">糖尿病</option>
          <option value="正常">正常</option>
        </select>
      </div>
    </div>

    <div class="images-grid">
      <div v-for="(image, index) in filteredImages" :key="image.id" class="image-card">
        <img :src="image.url" alt="眼底图像" @click="showImageDetail(image, index)">
        <div class="image-info">
          <p>疾病: {{ image.disease }}</p>
          <p>类型: {{ image.type }}</p>
          <p>描述: {{ image.description }}</p>
        </div>
        <div class="image-actions">
          <button class="view-btn" @click.stop="viewImage(image.url)">查看</button>
          <button class="delete-btn" @click.stop="showDeleteConfirm(index)">删除</button>
        </div>
      </div>
    </div>
    <div class="pagination">
      <button @click="previousPage" :disabled="currentPage === 1">上一页</button>
      <span>{{ currentPage }} / {{ totalPages }}</span>
      <button @click="nextPage" :disabled="currentPage === totalPages">下一页</button>
    </div>

    <!-- 删除确认对话框 -->
    <div v-if="showDeleteConfirmDialog" class="confirm-dialog">
      <div class="confirm-dialog-content">
        <p>确认删除这张图片吗？</p>
        <div class="confirm-buttons">
          <button @click="confirmDelete">是</button>
          <button @click="cancelDelete">否</button>
        </div>
      </div>
    </div>

    <!-- 图片查看模态框 -->
    <div v-if="showImageViewer" class="image-viewer">
      <div class="image-viewer-content">
        <img :src="currentImageView" alt="查看图片" @click="closeImageViewer">
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: 'LibraryView',
  data() {
    return {
      searchQuery: '',
      selectedDisease: '',
      selectedType: '',
      currentPage: 1,
      itemsPerPage: 6, // 每页显示6张图片（一行）
      images: [],
      diseases: [],
      types: [],
      uploadedImages: [], // 存储上传的图片信息
      showImageViewer: false,
      currentImageView: '',
      selectedUploadType: '',
      showDeleteConfirmDialog: false,
      currentDeleteIndex: -1
    };
  },
  computed: {
    filteredImages() {
      let filtered = this.images;

      if (this.searchQuery) {
        filtered = filtered.filter(image =>
          image.disease.includes(this.searchQuery) ||
          image.type.includes(this.searchQuery) ||
          image.description.includes(this.searchQuery)
        );
      }

      if (this.selectedDisease) {
        filtered = filtered.filter(image => image.diseaseId === this.selectedDisease);
      }

      if (this.selectedType) {
        filtered = filtered.filter(image => image.typeId === this.selectedType);
      }

      return filtered.slice(
        (this.currentPage - 1) * this.itemsPerPage,
        this.currentPage * this.itemsPerPage
      );
    },
    totalPages() {
      return Math.ceil(this.images.length / this.itemsPerPage);
    }
  },
  methods: {
    async fetchImages() {
      try {
        const response = await fetch('http://localhost:3000/api/library/images');
        const data = await response.json();
        this.images = data.images;
      } catch (error) {
        console.error('Error fetching images:', error);
      }
    },
    async fetchDiseases() {
      try {
        const response = await fetch('http://localhost:3000/api/library/diseases');
        const data = await response.json();
        this.diseases = data.diseases;
      } catch (error) {
        console.error('Error fetching diseases:', error);
      }
    },
    async fetchTypes() {
      try {
        const response = await fetch('http://localhost:3000/api/library/types');
        const data = await response.json();
        this.types = data.types;
      } catch (error) {
        console.error('Error fetching types:', error);
      }
    },
    searchImages() {
      this.currentPage = 1;
    },
    previousPage() {
      if (this.currentPage > 1) {
        this.currentPage--;
      }
    },
    nextPage() {
      if (this.currentPage < this.totalPages) {
        this.currentPage++;
      }
    },
    openFileInput() {
      if (this.selectedUploadType) {
        this.$refs.fileInput.click();
      } else {
        alert('请先选择图片类型');
      }
    },
    handleFileUpload(event) {
      const file = event.target.files[0];
      if (file) {
        const reader = new FileReader();
        reader.onload = (e) => {
          const newImage = {
            url: e.target.result,
            disease: '', // 可以根据需要设置疾病信息
            type: this.selectedUploadType, // 使用选择的类型
            description: '' // 可以根据需要设置描述信息
          };
          this.images.push(newImage);
        };
        reader.readAsDataURL(file);
      }
    },
    deleteImage(index) {
      this.images.splice(index, 1);
    },
    viewImage(url) {
      this.currentImageView = url;
      this.showImageViewer = true;
    },
    closeImageViewer() {
      this.showImageViewer = false;
    },
    showImageDetail(image) {
      // 可以在这里添加显示图片详情的逻辑
      console.log('图片详情:', image);
    },
    showDeleteConfirm(index) {
      this.currentDeleteIndex = index;
      this.showDeleteConfirmDialog = true;
    },
    confirmDelete() {
      if (this.currentDeleteIndex !== -1) {
        this.images.splice(this.currentDeleteIndex, 1);
        this.showDeleteConfirmDialog = false;
        this.currentDeleteIndex = -1;
      }
    },
    cancelDelete() {
      this.showDeleteConfirmDialog = false;
      this.currentDeleteIndex = -1;
    }
  },
  mounted() {
    this.fetchImages();
    this.fetchDiseases();
    this.fetchTypes();
  }
};
</script>

<style scoped>
@import '@/assets/css/global.css';
@import '@/assets/css/header.css';
@import '@/assets/css/library.css';


</style>